import React from 'react';

import { useNavigate } from 'react-router-dom';

import { IArticle } from '@apps/Articles/@types/articles.types';
import OneArticle from '@apps/Articles/components/OneArticle';
import CommentsWidget from '@apps/Comments/components/CommentsWidget';
import PageHeader from '@components/PageHeader';
import { AuthContext } from '@contexts/AuthContext';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohContainer from '@ui-kit/layout/Container';

interface IArticleOnePageProps {
  id: number;
}

const ArticleOnePage: React.FC<IArticleOnePageProps> = ({ id }) => {
  const [data, setData] = React.useState<IArticle>();
  const navigate = useNavigate();
  const authContext = React.useContext(AuthContext);

  return (
    <div>
      <Breadcrumb
        data={[
          { href: '/articles', text: 'Статьи' },
          { href: `/articles/${id}`, text: data?.name ?? '...', active: true },
        ]}
      />
      <PohContainer>
        <PageHeader title={data?.name ?? '...'}>
          {authContext.user?.id === data?.author?.id && (
            <PohButton
              size={ButtonSize.Small}
              variant={ButtonVariant.Success}
              onClick={() => navigate(`/articles/${id}/edit`)}
            >
              Редактировать
            </PohButton>
          )}
        </PageHeader>
        <OneArticle id={id} onDataReady={setData} />
        <br />
        <br />
        <CommentsWidget id_article={id} startText="Создать ветку чата" />
      </PohContainer>
    </div>
  );
};

export default ArticleOnePage;
